import{z as o,x as l,o as A,c as s,q as B,j as e,D as a,d as n,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"合规红线与收束","description":"","frontmatter":{"title":"合规红线与收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-compliance-map.md","filePath":"quant/cn-compliance-map.md","lastUpdated":1791063341000}'),C={name:"quant/cn-compliance-map.md"};function p(c,E,F,d,D,u){const t=l("Mermaid");return A(),s("div",null,[E[2]||(E[2]=B('<h1 id="合规红线与收束" tabindex="-1">合规红线与收束 <a class="header-anchor" href="#合规红线与收束" aria-label="Permalink to &quot;合规红线与收束&quot;">​</a></h1><div class="epigraph"><p>操纵认定从申报与成交的模式里推定，意图不在辩护清单的第一位；红线要写成行为加数据的清单，预防设计才落得进下单引擎。</p><footer>—— 据证券法与交易所异常交易监控口径整理</footer></div><p><a href="/quant/cn-capacity-cases">上一课</a>把容量曲线画进产品册，本课程最后一课处理上限之上的东西：红线，并把九课收成一张进场检查单。本课程到此收束。<a href="/quant/cn-quant-regulation-history">量化监管演进</a>已写监管脉络，<a href="/quant/cn-limit-auction">涨跌停与集合竞价</a>写过交易制度的边界设计，<a href="/quant/spoofing-layering">幌骚与分层</a>写过操纵行为的形态学。本课把红线写成可检查的清单：每条红线对应一类行为、一组监控数据、一种后果。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>量化的失败下限是合规下限：一个回测上再漂亮的策略，可能死于一笔被认定为异常交易的委托。红线的困难不在条文抽象，而在认定方式：交易行为的操纵认定从申报、成交、撤单的模式推定，策略意图不排在证据链第一位。所以清单必须写到数据层——什么行为模式触发什么监控指标，预防设计才能落到下单逻辑与组织流程，而不是停在培训材料里。</p><p><span class="marginnote">术语翻译：「推定」的意思是：不需要证明你「心里想操纵」，只要申报、成交、撤单的模式长得像操纵——比如高频报了又撤、自己实际控制的账户互相成交——就可以认定。意图辩解排在证据链后面，所以预防只能在行为模式上做，不能指望事后解释。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清单四类，每类落到行为与数据。交易行为类：连续交易或约定交易操纵、在自己实际控制的账户之间自成交、幌骗型申报撤单；预防设计在下单引擎——禁自成交过滤器、撤单率上限、申报节奏控制，并与报备台账的速率画像一致。信息类：利用未公开信息交易是个人刑责红线，机构侧的墙是隔离与通讯管控；舆情与另类数据的采集与使用另受数据合规约束。程序化义务类：报备不实或拒不报备、达认定标准而未履行额外义务——清单把<a href="/quant/cn-programmatic-filing">程序化交易的报备实践</a>的台账与速率监控接起来。载体合规类：适当性、披露与利益冲突，落在<a href="/quant/cn-fund-constraints">私募与公募的约束差异</a>的载体与<a href="/quant/cn-custody-counter">托管与柜台</a>的链路上。</p>',8)),(A(),e(i,null,{default:a(()=>[r(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DESIGN%5B%22%E7%AD%96%E7%95%A5%E8%AE%BE%E8%AE%A1%22%5D%20--%3E%20ENG%5B%22%E4%B8%8B%E5%8D%95%E5%BC%95%E6%93%8E%EF%BC%9A%E7%A6%81%E8%87%AA%E6%88%90%E4%BA%A4%2F%E6%92%A4%E5%8D%95%E7%8E%87%2F%E8%8A%82%E5%A5%8F%22%5D%0A%20%20DESIGN%20--%3E%20LEDGER%5B%22%E6%8A%A5%E5%A4%87%E5%8F%B0%E8%B4%A6%E4%B8%8E%E9%80%9F%E7%8E%87%E7%94%BB%E5%83%8F%E4%B8%80%E8%87%B4%22%5D%0A%20%20DESIGN%20--%3E%20INFO%5B%22%E4%BF%A1%E6%81%AF%E5%A2%99%E4%B8%8E%E6%95%B0%E6%8D%AE%E9%87%87%E9%9B%86%E5%90%88%E8%A7%84%22%5D%0A%20%20ENG%20--%3E%20LIVE%5B%22%E5%AE%9E%E7%9B%98%E7%9B%91%E6%8E%A7%22%5D%0A%20%20LEDGER%20--%3E%20LIVE%0A%20%20INFO%20--%3E%20LIVE%0A%20%20LIVE%20--%3E%20ALERT%7B%22%E8%A7%A6%E5%8F%91%E5%BC%82%E5%B8%B8%E4%BA%A4%E6%98%93%E6%8C%87%E6%A0%87%3F%22%7D%0A%20%20ALERT%20--%3E%7C%22%E6%98%AF%22%7C%20REVIEW%5B%22%E5%A4%8D%E6%A0%B8%E6%95%B4%E6%94%B9%EF%BC%8C%E5%BF%85%E8%A6%81%E6%97%B6%E6%9A%82%E5%81%9C%22%5D%0A%20%20ALERT%20--%3E%7C%22%E5%90%A6%22%7C%20RUN%5B%22%E6%8C%81%E7%BB%AD%E8%BF%90%E8%A1%8C%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>红线为什么用「行为加数据」写。交易所的异常交易监控跑在申报、成交、撤单的统计特征上：撤单率、申报速率、成交账户间的关联、价格逼近涨跌停时的排单与撤单行为（涨跌停边是高危区，见<a href="/quant/cn-limit-auction">涨跌停与集合竞价</a>）。监管演进的方向是把更多行为纳入监控并抬高违规成本（<a href="/quant/cn-quant-regulation-history">量化监管演进</a>），清单因此是移动的，检查单要留「当期口径」一栏，按季度重读。组织侧的对应物是留痕：报备台账、策略版本、下单引擎的风控参数都要能复现某个交易日的决策链。</p><p><span class="marginnote">预防设计里最便宜的一条是禁自成交过滤器：在报盘前按实际控制关系合并账户查重，成本是一次账户树维护；省掉它，一次自成交认定可能就把整条产品线停掉。</span></p><p><span class="marginnote">数字实例：某策略日内申报 10000 笔、成交 1500 笔、撤单 8500 笔，撤单率 85%——无论当期阈值定在 50% 还是 80%，这个画像都必然进入异常筛查。把它压下来不是合规部门的事，而是下单引擎里撤单率上限与申报节奏控制两个参数的职责。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课是合规意识的检查工具，不构成法律意见；认定标准、阈值与处罚尺度以当期法律法规与交易所、协会规则为准。收束全课程，检查次序固定如下：工具可得——贴水与券源两条空头腿；身份合规——报备台账；成本可行——费率预算与换手上界；供给可靠——数据栈与时点质量；载体匹配——公募私募约束清单；链路可控——托管与柜台；规模可容——容量曲线；红线可查——本课清单。任何一项不过，策略不上生产。</p>',6)),(A(),e(i,null,{default:a(()=>[r(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%AD%96%E7%95%A5%E5%80%99%E9%80%89%22%5D%20--%3E%20C1%5B%221%20%E5%B7%A5%E5%85%B7%E5%8F%AF%E5%BE%97%EF%BC%9A%E8%B4%B4%E6%B0%B4%E4%B8%8E%E5%88%B8%E6%BA%90%22%5D%0A%20%20C1%20--%3E%20C2%5B%222%20%E8%BA%AB%E4%BB%BD%E5%90%88%E8%A7%84%EF%BC%9A%E6%8A%A5%E5%A4%87%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20C2%20--%3E%20C3%5B%223%20%E6%88%90%E6%9C%AC%E5%8F%AF%E8%A1%8C%EF%BC%9A%E8%B4%B9%E7%8E%87%E4%B8%8E%E6%8D%A2%E6%89%8B%E4%B8%8A%E7%95%8C%22%5D%0A%20%20C3%20--%3E%20C4%5B%224%20%E4%BE%9B%E7%BB%99%E5%8F%AF%E9%9D%A0%EF%BC%9A%E6%95%B0%E6%8D%AE%E6%A0%88%E4%B8%8E%E6%97%B6%E7%82%B9%22%5D%0A%20%20C4%20--%3E%20C5%5B%225%20%E8%BD%BD%E4%BD%93%E5%8C%B9%E9%85%8D%EF%BC%9A%E5%85%AC%E5%8B%9F%2F%E7%A7%81%E5%8B%9F%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20C5%20--%3E%20C6%5B%226%20%E9%93%BE%E8%B7%AF%E5%8F%AF%E6%8E%A7%EF%BC%9A%E6%89%98%E7%AE%A1%E4%B8%8E%E6%9F%9C%E5%8F%B0%22%5D%0A%20%20C6%20--%3E%20C7%5B%227%20%E8%A7%84%E6%A8%A1%E5%8F%AF%E5%AE%B9%EF%BC%9A%E5%AE%B9%E9%87%8F%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20C7%20--%3E%20C8%5B%228%20%E7%BA%A2%E7%BA%BF%E5%8F%AF%E6%9F%A5%EF%BC%9A%E6%9C%AC%E8%AF%BE%E6%B8%85%E5%8D%95%22%5D%0A%20%20C8%20--%3E%7C%22%E5%85%A8%E9%83%A8%E9%80%9A%E8%BF%87%22%7C%20PROD%5B%22%E4%B8%8A%E7%94%9F%E4%BA%A7%22%5D%0A%20%20C8%20--%3E%7C%22%E4%BB%BB%E4%B8%80%E4%B8%8D%E8%BF%87%22%7C%20STOP%5B%22%E4%B8%8D%E4%B8%8A%E7%94%9F%E4%BA%A7%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">常见误区：初学者容易以为合规是法务的事、研究只管信号。实际上红线四类里有三类——自成交过滤、撤单率上限、报备与实际速率一致——必须写进下单引擎的代码。代码里少一个过滤器与故意违规，在认定后果上没有区别。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>红线四类：交易行为、信息、程序化义务、载体合规，每条落到行为模式与监控数据。</li><li>操纵认定从申报成交模式推定，预防设计在下单引擎与组织墙，不在事后解释。</li><li>报备台账与速率监控必须勾稽，报备不实本身就是红线。</li><li>全课程检查次序：工具、身份、成本、供给、载体、链路、容量、红线，一项不过不上生产。</li><li>出处：证券法、期货和衍生品法与交易所异常交易监控口径；监管脉络见<a href="/quant/cn-quant-regulation-history">量化监管演进</a>。</li></ul>',3))])}const _=o(C,[["render",p]]);export{m as __pageData,_ as default};
